// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface AttendanceDayOut {
  attendance_date: string;
  employee_id: number;
  emp_number: string;
  full_name: string;
  department_name: string | null;
  status: "Present" | "Late" | "Absent" | "HalfDay" | "Leave" | "Holiday" | "Off";
  first_punch: string | null;
  last_punch: string | null;
  worked_minutes: number;
  late_minutes: number;
}

/** A punch (badge tap, roll call or manual correction). */
export interface AttendanceLogOut {
  attendance_log_id: number;
  employee_id: number;
  badge_code: string | null;
  station_id: string | null;
  punch_time: string;
  punch_type: "In" | "Out";
  source: "Badge" | "RollCall" | "Manual";
  manual_reason: string | null;
  entered_by: number | null;
  /** The duty date the punch counts for */
  attendance_date: string;
  created_at: string;
}

export interface ManualPunchIn {
  employee_id: number;
  /** With a UTC offset; without one it is the hospital's local time */
  punch_time: string;
  reason: string;
  /** The date of the duty this punch is for. Default: worked out from the schedule (the exit after a night shift counts for the night before). Only needed when that guess is wrong; must be the punch's own date or the day before or after */
  attendance_date?: string | null;
}

export interface AttendanceSummaryOut {
  summary_id: number;
  employee_id: number;
  attendance_date: string;
  shift_pattern_id: number | null;
  first_punch: string | null;
  last_punch: string | null;
  worked_minutes: number;
  late_minutes: number;
  status: "Present" | "Late" | "Absent" | "HalfDay" | "Leave" | "Holiday" | "Off";
  computed_at: string;
  row_version: number;
  /** False: an existing day was changed */
  inserted: boolean;
}

export interface ShiftAssignIn {
  /** The fixed default shift; null = the employee works to the duty roster only (a day without a roster entry is a rest day) */
  shift_pattern_id: number | null;
  effective_from: string;
  /** With a default shift, required: the ISO weekdays this person is off (1 = Monday … 7 = Sunday). A hospital never closes, so each person has their own; [] = works every day (the day beyond the weekly allowance is paid as extra duty) */
  weekly_off_days?: number[] | null;
}

/** The default shift from a date on. For roster-only staff (shift_pattern_id null) only employee_id, shift_pattern_id, effective_from and weekly_off_days are sent. */
export interface ShiftAssignmentOut {
  assignment_id?: number | null;
  employee_id: number;
  shift_pattern_id: number | null;
  effective_from: string;
  effective_to?: string | null;
  /** ISO weekdays (1 = Monday … 7 = Sunday); null for roster-only staff */
  weekly_off_days: number[] | null;
  row_version?: number | null;
}

export interface HolidayOut {
  holiday_id: number;
  holiday_date: string;
  name: string;
  notes: string | null;
  is_active: boolean;
  created_by: number | null;
  created_at: string;
  row_version: number;
}

export interface RollCallSheetOut {
  roster_date: string;
  entries: RollCallEntryOut[];
}

export interface RollCallEntryOut {
  roster_id: number;
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  roster_date: string;
  shift_pattern_id: number;
  shift_name: string;
  start_time: string;
  end_time: string;
  duty_area: "Ward" | "Department" | "Emergency" | "OT" | "Facility" | "Other";
  ward_id: number | null;
  ward_name: string | null;
  department_id: number | null;
  department_name: string | null;
  zone_label: string | null;
  is_on_call: boolean;
  notes: string | null;
  status: "Active" | "Cancelled";
  cancel_reason: string | null;
  /** Taken over from a colleague through this approved duty swap */
  swap_id: number | null;
  row_version: number;
  /** The beds of a ward duty (the nurse's "my beds") */
  bed_ids: number[];
  /** The first arrival punch of the duty (null: not arrived) */
  first_in: string | null;
  first_source: "Badge" | "RollCall" | "Manual" | null;
}

export interface RollCallIn {
  roster_date: string;
  present: Present[];
}

export interface Present {
  employee_id: number;
  /** Arrival time; default now (required for an earlier day's shift). Without a UTC offset it is the hospital's local time */
  at?: string | null;
}

export interface RollCallOut {
  roster_date: string;
  recorded: AttendanceLogOut[];
  /** Staff who had already punched in */
  skipped: RollCallSkippedOut[];
}

export interface RollCallSkippedOut {
  employee_id: number;
  full_name: string;
  reason: string;
}

/** Daily attendance flags (Present / Late / Absent / HalfDay / Leave) — GET /api/v1/hr/attendance (who may call: holders of hr.attendance.view). */
export function attendance(query?: { date_from?: string | null; date_to?: string | null; employee_id?: number | null; department_id?: number | null }): Promise<AttendanceDayOut[]> {
  return api<AttendanceDayOut[]>("GET", withQuery(`/hr/attendance`, query), undefined);
}

/** Raw punches of one employee for one duty date — GET /api/v1/hr/attendance/punches (who may call: holders of hr.attendance.view). */
export function punches(query: { employee_id: number; day: string }): Promise<AttendanceLogOut[]> {
  return api<AttendanceLogOut[]>("GET", withQuery(`/hr/attendance/punches`, query), undefined);
}

/** Manual punch correction (reasoned, audited) — POST /api/v1/hr/attendance/manual (who may call: holders of hr.attendance.manual). */
export function manualPunch(body: ManualPunchIn): Promise<AttendanceLogOut> {
  return api<AttendanceLogOut>("POST", `/hr/attendance/manual`, body, { idempotent: true });
}

/** (Re)compute the daily flags for a date (the worker does this nightly) — POST /api/v1/hr/attendance/compute (who may call: holders of hr.attendance.view). */
export function compute(query: { day: string }): Promise<AttendanceSummaryOut[]> {
  return api<AttendanceSummaryOut[]>("POST", withQuery(`/hr/attendance/compute`, query), undefined);
}

/** Set the default shift from a date (or roster-only) — POST /api/v1/hr/employees/{employee_id}/shift (who may call: holders of hr.shift.manage). */
export function assignShift(employee_id: number, body: ShiftAssignIn): Promise<ShiftAssignmentOut> {
  return api<ShiftAssignmentOut>("POST", `/hr/employees/${employee_id}/shift`, body, { idempotent: true });
}

/** Public holidays of a year (or a date range) — GET /api/v1/holidays (who may call: any logged-in user). */
export function listHolidays(query?: { year?: number | null; date_from?: string | null; date_to?: string | null; include_inactive?: boolean }): Promise<HolidayOut[]> {
  return api<HolidayOut[]>("GET", withQuery(`/holidays`, query), undefined);
}

/** Roll-call sheet: who is rostered today and who has arrived — GET /api/v1/rosters/roll-call (who may call: holders of attendance.roll_call). */
export function rollCallSheet(query?: { roster_date?: string | null; shift_pattern_id?: number | null; ward_id?: number | null }): Promise<RollCallSheetOut> {
  return api<RollCallSheetOut>("GET", withQuery(`/rosters/roll-call`, query), undefined);
}

/** Mark rostered staff present (no badge station) — POST /api/v1/rosters/roll-call (who may call: holders of attendance.roll_call). */
export function takeRollCall(body: RollCallIn): Promise<RollCallOut> {
  return api<RollCallOut>("POST", `/rosters/roll-call`, body, { idempotent: true });
}
